code.source:
#include <iostream>
using namespace std;

int main() {
    int fish = 7;
    double weight = fish;
    double price = 9.99;
    int whole = price;
    cout << weight << endl;
    cout << whole << endl;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int passed = 7, total = 8;
    double ratio = static_cast<double>(passed) / total;
    cout << ratio << endl;
    char letter = 'A';
    cout << static_cast<int>(letter) << endl;
    return 0;
}

